const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.querySelector('#reset-analytics')?.addEventListener('click',()=>{try{localStorage.removeItem('fenek_analytics_consent')}catch{}location.reload()});